namespace Hexalith.Platform.Protection;

/// <summary>Hash-bound reference-only installation for one independently operated native role service. No key, native receipt or observation is generated by the transport.</summary>
/// <param name="Schema">Exact role-program contract.</param><param name="Role">executor, observer or enrollment.</param><param name="Identity">Independent role identity.</param>
/// <param name="Endpoint">Dedicated HTTPS native role endpoint.</param><param name="CredentialReference">The role's own env reference.</param>
/// <param name="PublicAnchorFile">Actual native role public P-256 verifier.</param><param name="PublicAnchorSha256">Pinned public bytes.</param>
public sealed record ProtectionQualificationRoleInstallation(string Schema, string Role, string Identity, string Endpoint,
    string CredentialReference, string PublicAnchorFile, string PublicAnchorSha256);
